static int decode_case(const Case *c) {
    size_t px = (size_t)c->w * (size_t)c->h * (size_t)c->channels;
    size_t cap = px + (size_t)c->w * 8 + 4096;
    unsigned char *out = malloc(cap);
    unsigned char *scratch = malloc(c->flen);
    WubuPixmap info = { 0 };
    int err = 0;
    if (wubu_pixmap_info(c->file, c->flen, &info, &err) != 0) {
        printf("  [FAIL] %-14s info: %s\n", c->name, wubu_pixmap_reason(err));
        free(out); free(scratch); return 0;
    }
    if (info.width != c->w || info.height != c->h || info.channels != c->channels) {
        printf("  [FAIL] %-14s info %dx%d/%dch want %dx%d/%dch\n", c->name,
               info.width, info.height, info.channels, c->w, c->h, c->channels);
        free(out); free(scratch); return 0;
    }
    if (wubu_pixmap_decode(c->file, c->flen, scratch, c->flen, out, cap, &info, &err) != 0) {
        printf("  [FAIL] %-14s decode: %s\n", c->name, wubu_pixmap_reason(err));
        free(out); free(scratch); return 0;
    }
    int good = memcmp(out, c->expect, c->elen) == 0;
    if (!good) printf("  [FAIL] %-14s pixels differ\n", c->name);
    free(out); free(scratch);
    return good;
}

static void refuses(const char *what, const void *data, size_t len, size_t scratch_cap,
                    size_t out_cap, int want) {
    unsigned char *out = malloc(out_cap ? out_cap : 1);
    unsigned char *scr = malloc(scratch_cap ? scratch_cap : 1);
    WubuPixmap img = { 0 };
    int err = 0;
    (void)wubu_pixmap_decode(data, len, scr, scratch_cap, out, out_cap, &img, &err);
    if (err == want) pass++;
    else { printf("  [FAIL] %-20s expected %d (%s), got %d (%s)\n", what, want,
                  wubu_pixmap_reason(want), err, wubu_pixmap_reason(err)); fail++; }
    free(out); free(scr);
}

int main(void) {
    printf("=== wubu_pixmap (slerm gate, SLERM-2002 stage 1) ===\n");
    for (size_t i = 0; i < sizeof CASES / sizeof CASES[0]; i++) {
        if (decode_case(&CASES[i])) pass++; else fail++;
    }

    refuses("bad CRC", f_badcrc, sizeof f_badcrc, sizeof f_badcrc, 4096, WUBU_PIXMAP_CORRUPT);
    refuses("truncated", f_trunc, sizeof f_trunc, sizeof f_trunc, 4096, WUBU_PIXMAP_TRUNCATED);
    { static unsigned char p[sizeof f_png_grey_f0];
      memcpy(p, f_png_grey_f0, sizeof p);
      p[24] = 16;                      /* bit depth inside IHDR: a variant we refuse */
      int err = 0; WubuPixmap img = { 0 }; unsigned char out[4096];
      (void)wubu_pixmap_decode(p, sizeof p, p, sizeof p, out, sizeof out, &img, &err);
      if (err == WUBU_PIXMAP_UNSUPPORTED || err == WUBU_PIXMAP_CORRUPT) pass++;
      else { printf("  [FAIL] 16-bit PNG accepted (%s)\n", wubu_pixmap_reason(err)); fail++; } }
    refuses("scratch too small", f_png_rgb_f0, sizeof f_png_rgb_f0, 16, 4096, WUBU_PIXMAP_SCRATCH);
    refuses("out too small", f_png_rgb_f0, sizeof f_png_rgb_f0, sizeof f_png_rgb_f0, 8, WUBU_PIXMAP_OVERFLOW);
    { static const unsigned char junk[] = { 'h','e','l','l','o',' ','w','u' };
      refuses("not an image", junk, sizeof junk, 64, 64, WUBU_PIXMAP_FORMAT); }

    printf("\n=== %d passed, %d failed ===\n", pass, fail);
    return fail ? 1 : 0;
}
